  <script>
    const carousel = document.getElementById('trending-carousel');
    const nextBtn = document.getElementById('carousel-next');

    nextBtn.addEventListener('click', () => {
      const scrollAmount = Math.max(320, Math.round(carousel.clientWidth * 0.82));
      carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });

    const faqItems = Array.from(document.querySelectorAll('.faq-item'));

    faqItems.forEach((item) => {
      const trigger = item.querySelector('.faq-question');
      trigger.addEventListener('click', () => {
        faqItems.forEach((other) => {
          const button = other.querySelector('.faq-question');
          const isActive = other === item && !other.classList.contains('active');
          other.classList.toggle('active', isActive);
          button.setAttribute('aria-expanded', isActive ? 'true' : 'false');
        });
      });
    });

    document.querySelectorAll('.email-group').forEach((form) => {
      form.addEventListener('submit', (event) => {
        const input = form.querySelector('input[type="email"]');
        if (!input.checkValidity()) {
          event.preventDefault();
          input.reportValidity();
        } else {
          event.preventDefault();
        }
      });
    });
  </script>
